<x-layouts.member :title="$department->name" :ministry-name="$settings->name" :features="$features"><header class="department-chat-heading"><a href="{{ route('member.departments') }}">← My departments</a><div><span class="member-tile-icon"><x-ui.icon name="departments"/></span><div><p>DEPARTMENT CHAT</p><h1>{{ $department->name }}</h1><small>{{ str($department->role)->headline() }} · Private to active members</small></div></div></header>@if(session('status'))<div class="member-notice member-notice-success">{{ session('status') }}</div>@endif @if($errors->any())<div class="member-notice member-notice-error">{{ $errors->first() }}</div>@endif<section class="department-chat-shell"><header><div><strong>Team conversation</strong><span>{{ $department->description ?: 'A private space for this department.' }}</span></div><span class="department-chat-private"><x-ui.icon name="security" :size="14"/> Members only</span></header>@if($department->discussion_enabled)<div class="department-chat-feed">@forelse($messages as $message)<article @class(['is-own'=>$message->person_id===$person->id]) id="message-{{ $message->id }}">@if($message->parent_content)<blockquote>{{ str($message->parent_content)->limit(120) }}</blockquote>@endif<div class="department-chat-avatar">{{ mb_strtoupper(mb_substr($message->first_name,0,1).mb_substr($message->last_name,0,1)) }}</div><div><header><strong>{{ trim($message->first_name.' '.$message->last_name) }}</strong><time datetime="{{ $message->created_at }}">{{ \Illuminate\Support\Carbon::parse($message->created_at)->diffForHumans() }} @if($message->edited_at)· edited@endif</time></header><p>{{ $message->content }}</p><footer><button type="button" onclick="document.getElementById('reply-{{ $message->id }}').hidden=false">Reply</button>@if($message->person_id===$person->id)<button type="button" onclick="document.getElementById('edit-{{ $message->id }}').hidden=false">Edit</button><form method="POST" action="{{ route('member.departments.messages.delete',[$department->id,$message->id]) }}">@csrf @method('DELETE')<button type="submit">Delete</button></form>@endif</footer><form hidden id="reply-{{ $message->id }}" class="department-chat-inline" method="POST" action="{{ route('member.departments.messages.store',$department->id) }}">@csrf<input type="hidden" name="parent_message_id" value="{{ $message->id }}"><textarea name="content" rows="2" maxlength="2000" required placeholder="Reply to {{ $message->first_name }}"></textarea><button>Send reply</button></form>@if($message->person_id===$person->id)<form hidden id="edit-{{ $message->id }}" class="department-chat-inline" method="POST" action="{{ route('member.departments.messages.update',[$department->id,$message->id]) }}">@csrf @method('PUT')<textarea name="content" rows="2" maxlength="2000" required>{{ $message->content }}</textarea><button>Save edit</button></form>@endif</div></article>@empty<div class="member-empty-state"><strong>No messages yet</strong><p>Start the department conversation.</p></div>@endforelse</div><form class="department-chat-composer" method="POST" action="{{ route('member.departments.messages.store',$department->id) }}">@csrf<div class="department-chat-avatar">{{ mb_strtoupper(mb_substr($person->first_name,0,1).mb_substr($person->last_name,0,1)) }}</div><label><span class="sr-only">Message the department</span><textarea name="content" rows="3" maxlength="2000" required placeholder="Message {{ $department->name }}…"></textarea></label><button class="button" type="submit">Send</button></form>@else<div class="member-empty-state"><strong>Chat is unavailable</strong><p>Department leaders have turned off discussion for this space.</p></div>@endif</section>@if($department->role==='member')<form class="department-leave-form" method="POST" action="{{ route('member.departments.leave',$department->id) }}">@csrf @method('DELETE')<button type="submit">Leave department</button></form>@endif</x-layouts.member>
